import re
S='/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad'
mech=open('/home/user/fortress-landing-26/explorations/compile-ladder/climb-batch-26/record-landing/mech-1.md').read()
new=open('/home/user/fortress-landing-26/explorations/coordinator/PLAN.md').read().split('\n')
old=open(S+'/oldplan.md').read().split('\n')
owed=open('/home/user/fortress-landing-26/explorations/compile-ladder/climb-batch-26/record-landing/owed.md').read()
homes={}
for m in re.finditer(r'^- (C\d+) \| home: ([^|]*)',owed,re.M):
    for n in re.findall(r'PLAN\.md:(\d+)',m.group(2)): homes.setdefault(int(n),[]).append(m.group(1))
    for a,b in re.findall(r'PLAN\.md:(\d+)-(\d+)',m.group(2)):
        for n in range(int(a),int(b)+1): homes.setdefault(n,[]).append(m.group(1))
# C52 lists :36, :52 ...
m=re.search(r'^- C52 \| home: ([^|]*)',owed,re.M)
for n in re.findall(r':(\d+)',m.group(1)): homes.setdefault(int(n),[]).append('C52')
looks=re.findall(r'^LOOK PLAN\.md:(\d+)',mech,re.M)
print(len(looks))
miss=[]
for l in looks:
    l=int(l); line=new[l-1]
    idx=[i+1 for i,o in enumerate(old) if o==line]
    if not idx: miss.append((l,'notfound',line[:100])); continue
    o=idx[0]
    if o not in homes: miss.append((l,o,line[:100]))
for x in miss: print(x)
EOF

